style.css:
@-moz-document domain("nosleep.page") {
/* =========================
     GLOBAL DARK THEME
     ========================= */

  :root {
    color-scheme: dark;

    --ns-bg: #090d12;
    --ns-bg-2: #0d131a;
    --ns-card: #111820;
    --ns-card-hover: #151e27;
    --ns-border: #263340;
    --ns-border-soft: #1c2731;

    --ns-text: #e8eef3;
    --ns-text-secondary: #a8b4bf;
    --ns-text-muted: #73808b;

    --ns-accent: #14b8a6;
    --ns-accent-hover: #21c7b5;
    --ns-accent-soft: rgba(20, 184, 166, 0.12);
    --ns-accent-border: rgba(20, 184, 166, 0.55);
  }

  html,
  body {
    background: var(--ns-bg) !important;
    color: var(--ns-text) !important;
  }

  body {
    min-height: 100vh !important;
  }


  /* =========================
     MAIN PAGE BACKGROUND
     ========================= */

  main {
    background:
      radial-gradient(
        circle at 50% 22%,
        rgba(20, 184, 166, 0.07),
        transparent 30%
      ),
      linear-gradient(
        180deg,
        #0b1016 0%,
        #090d12 100%
      ) !important;
  }


  /* =========================
     MAIN TIMER CARD
     ========================= */

  main > div.bg-white,
  section > div.bg-white {
    background: var(--ns-card) !important;
    color: var(--ns-text) !important;
    border: 1px solid var(--ns-border-soft) !important;
    box-shadow:
      0 18px 50px rgba(0, 0, 0, 0.38),
      0 0 0 1px rgba(255, 255, 255, 0.015) !important;
  }


  /* =========================
     TIMER / CENTRAL RING
     ========================= */

  #wake-toggle {
    background: #0c1218 !important;
    border-color: #293640 !important;
    box-shadow:
      inset 0 0 30px rgba(0, 0, 0, 0.55),
      0 8px 30px rgba(0, 0, 0, 0.35) !important;
  }

  #wake-toggle:hover {
    background: #101820 !important;
    border-color: #34434f !important;
  }

  #wake-toggle:focus-visible {
    outline: 2px solid var(--ns-accent) !important;
    outline-offset: 5px !important;
  }

  #progress-ring {
    color: var(--ns-accent) !important;
    filter:
      drop-shadow(0 0 5px rgba(20, 184, 166, 0.32))
      drop-shadow(0 0 12px rgba(20, 184, 166, 0.12)) !important;
  }

  #toggle-icon {
    color: #dce7ed !important;
  }

  #timer-text {
    color: #f0f7f7 !important;
    font-weight: 600 !important;
    letter-spacing: 0.03em !important;
  }


  /* =========================
     DURATION BUTTONS
     ========================= */

  .duration-chip {
    background: #0d151b !important;
    color: #4bd2c2 !important;
    border-color: var(--ns-accent-border) !important;
  }

  .duration-chip:hover {
    background: var(--ns-accent-soft) !important;
    color: #65e0d2 !important;
    border-color: var(--ns-accent) !important;
  }

  #custom-btn,
  #custom-start {
    background: #109e8e !important;
    color: white !important;
    border: 1px solid rgba(255, 255, 255, 0.04) !important;
    box-shadow: none !important;
  }

  #custom-btn:hover,
  #custom-start:hover {
    background: var(--ns-accent-hover) !important;
  }


  /* =========================
     CUSTOM TIME INPUT
     ========================= */

  #custom-input {
    background: #0a1117 !important;
    color: var(--ns-text) !important;
    border: 1px solid var(--ns-border) !important;
  }

  #custom-input:focus {
    border-color: var(--ns-accent) !important;
    outline: none !important;
    box-shadow: 0 0 0 3px rgba(20, 184, 166, 0.12) !important;
  }

  input[type="time"] {
    color-scheme: dark !important;
  }


  /* =========================
     STATS
     ========================= */

  #stats {
    color: var(--ns-text-secondary) !important;
  }

  #today-min,
  #week-hr,
  #week-min {
    color: #e8f5f3 !important;
    font-weight: 600 !important;
  }


  /* =========================
     FAQ SECTION
     ========================= */

  section {
    color: var(--ns-text) !important;
  }

  section > div {
    background: var(--ns-card) !important;
    border-color: var(--ns-border-soft) !important;
  }

  section .divide-gray-200,
  section .dark\:divide-gray-700 {
    border-color: var(--ns-border-soft) !important;
  }

  details {
    background: #0d141b !important;
    border-color: var(--ns-border) !important;
    color: var(--ns-text) !important;
  }

  details:hover {
    background: var(--ns-card-hover) !important;
  }

  details[open] {
    background: #101820 !important;
    border-color: #30424d !important;
  }

  summary {
    color: #edf4f7 !important;
  }

  details p {
    color: var(--ns-text-secondary) !important;
  }

  details label {
    color: var(--ns-text-secondary) !important;
  }


  /* =========================
     LINKS
     ========================= */

  a,
  #reset-stats,
  #reset-colors {
    color: #35c9b8 !important;
  }

  a:hover,
  #reset-stats:hover,
  #reset-colors:hover {
    color: #63dfd1 !important;
  }


  /* =========================
     COLOR PICKERS
     ========================= */

  input[type="color"] {
    background: #0c1319 !important;
    border-color: var(--ns-border) !important;
    border-radius: 7px !important;
  }


  /* =========================
     OVERRIDE TAILWIND LIGHT COLORS
     ========================= */

  .bg-gray-50 {
    background: var(--ns-bg) !important;
  }

  .bg-white {
    background: var(--ns-card) !important;
  }

  .text-gray-700 {
    color: var(--ns-text-secondary) !important;
  }

  .text-gray-800 {
    color: var(--ns-text) !important;
  }

  .text-gray-200,
  .text-gray-300,
  .text-gray-100 {
    color: var(--ns-text) !important;
  }

  .border-gray-200,
  .border-gray-300 {
    border-color: var(--ns-border) !important;
  }

  .hover\:bg-gray-50:hover {
    background: var(--ns-card-hover) !important;
  }


  /* =========================
     SCROLLBAR
     ========================= */

  * {
    scrollbar-width: thin;
    scrollbar-color: #34434c #090d12;
  }

  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #090d12;
  }

  ::-webkit-scrollbar-thumb {
    background: #34434c;
    border: 2px solid #090d12;
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #435763;
  }


  /* =========================
     BUY ME A COFFEE BUTTON
     ========================= */

  #bmc-wbtn {
    background: #101a20 !important;
    border: 1px solid #294049 !important;
    box-shadow:
      0 8px 24px rgba(0, 0, 0, 0.45),
      0 0 0 1px rgba(20, 184, 166, 0.08) !important;
  }

  #bmc-wbtn:hover {
    background: #16242b !important;
    transform: translateY(-1px) !important;
  }


  /* =========================
     REMOVE WHITE FLASH / EMPTY AREAS
     ========================= */

  html,
  body,
  main,
  section {
    background-color: var(--ns-bg) !important;
  }


  /* =========================
     SELECTION
     ========================= */

  ::selection {
    background: rgba(20, 184, 166, 0.3);
    color: #ffffff;
  }
}
